// Turns the configured comma-separated feed list into one item per feed URL, so the RSS node
// downstream fetches each one independently.
const urls = ($vars.SECURITY_DIGEST_FEED_URLS || '').split(',').map(s => s.trim()).filter(Boolean);
return urls.map(url => ({ json: { feed_url: url } }));

// Keeps only items published within the lookback window AND matching at least one relevance
// keyword -- this is plain keyword filtering, not real analysis or judgment about what's actually
// important.
const items = $input.all().map(i => i.json);
const RELEVANCE_KEYWORDS = ($vars.RELEVANCE_KEYWORDS || 'small firm,solo firm,law firm,breach,ransomware,data protection,compliance,privacy law').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const DIGEST_LOOKBACK_DAYS = Number($vars.DIGEST_LOOKBACK_DAYS || 7);
const cutoff = Date.now() - DIGEST_LOOKBACK_DAYS * 24 * 60 * 60 * 1000;

const relevant = items.filter(item => {
  const pubDate = item.isoDate || item.pubDate;
  const publishedRecently = pubDate ? (new Date(pubDate).getTime() >= cutoff) : true;
  const text = `${item.title || ''} ${item.contentSnippet || item.content || ''}`.toLowerCase();
  const isRelevant = RELEVANCE_KEYWORDS.some(k => text.includes(k));
  return publishedRecently && isRelevant;
});

return relevant.map(item => {
  const text = `${item.title || ''} ${item.contentSnippet || item.content || ''}`.toLowerCase();
  const matchedKeyword = RELEVANCE_KEYWORDS.find(k => text.includes(k)) || '';
  return { json: {
    title: item.title || '(untitled)',
    link: item.link || '',
    source_feed: item.meta?.title || item.link || '',
    published_date: item.isoDate || item.pubDate || '',
    snippet: (item.contentSnippet || '').slice(0, 300),
    matched_keyword: matchedKeyword,
  } };
});

// A templated, keyword-driven blurb -- not real analysis. This is the entire 'why this matters'
// content, deliberately kept simple and non-interpretive.
const items = $input.all().map(i => i.json);

const BLURB_BY_KEYWORD = {
  'breach': 'A reminder that breach notification obligations apply to firms of every size, not just large ones.',
  'ransomware': 'Ransomware increasingly targets smaller organizations precisely because they often have fewer defenses in place.',
  'data protection': 'Data protection requirements keep expanding, and solo/small firms are not exempt just because of size.',
  'compliance': 'Compliance guidance written for enterprise IT rarely translates directly to a solo or small practice — worth a plain-English read.',
  'privacy law': 'Privacy law changes can affect client intake and data handling even for firms that never thought of themselves as a target.',
};
const DEFAULT_BLURB = 'Worth a look for how it might apply at solo/small-firm scale.';

const digestItems = items.map(item => ({
  ...item,
  why_it_matters: BLURB_BY_KEYWORD[item.matched_keyword] || DEFAULT_BLURB,
}));

const draftLines = digestItems.length
  ? digestItems.map(i => `- ${i.title} (${i.source_feed})\n  ${i.why_it_matters}\n  ${i.link}`).join('\n\n')
  : '(no relevant items found this week)';

return [{ json: {
  item_count: digestItems.length,
  draft_content: draftLines,
  items: digestItems,
} }];

// Reads deal-equivalent fields back from 'Assign Digest ID' by name, not $json -- the Sheets
// append node in between echoes back its own written row, not the original structured data,
// same gotcha already found and fixed in this catalog's other Sheets-logging templates.
const d = $('Assign Digest ID').item.json;
return { json: {
  ...d,
  recipient: $vars.CONTENT_REVIEWER_EMAIL,
  subject: `Security digest draft ready for review — ${d.item_count} item(s)`,
  message: `This week's security/compliance digest draft (${d.digest_id}) is ready:\n\n${d.draft_content}\n\nThis is informational monitoring only, not advice or analysis -- review, polish, and approve before it goes into the newsletter/Field Notes pipeline.`,
} };
